import{_ as i,o as c,c as n,a5 as a}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"ADR-003 — RabbitMQ cho Async Publishing","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-003-rabbitmq.md","filePath":"adr/ADR-003-rabbitmq.md"}'),t={name:"adr/ADR-003-rabbitmq.md"};function s(o,e,r,l,h,b){return c(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-003-—-rabbitmq-cho-async-publishing" tabindex="-1">ADR-003 — RabbitMQ cho Async Publishing <a class="header-anchor" href="#adr-003-—-rabbitmq-cho-async-publishing" aria-label="Permalink to &quot;ADR-003 — RabbitMQ cho Async Publishing&quot;">​</a></h1><p><strong>Status:</strong> Accepted</p><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Khi Task (Post-type) hoàn tất Approval Sequence và tới lịch đăng, business-service cần đẩy nội dung lên Social Platform (Facebook/Instagram/TikTok/Threads) qua <code>publisher-service</code>. Cần chọn giữa gọi REST đồng bộ trực tiếp hay message queue bất đồng bộ.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>Dùng <strong>RabbitMQ</strong> (exchange <code>brandhub.publishing</code>, type <code>direct</code>) làm kênh giao tiếp business-service → publisher-service, publisher-service gửi callback HTTP ngược lại sau khi xử lý xong (xem <code>docs/architecture/rabbitmq-publisher-contract.html</code>).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p><strong>Tích cực:</strong></p><ul><li>Social API latency không ổn định (2–30s, có lúc timeout) — async queue tách rời request-issuing khỏi actual execution, business-service không bị block.</li><li>Retry isolation: lỗi publish 1 platform (vd: Facebook rate limit) không ảnh hưởng job khác đang chờ — mỗi message retry độc lập với backoff 30s→60s→120s→DLQ.</li><li>publisher-service scale độc lập theo tải publish (nhiều campaign lớn cùng lúc) mà không cần scale business-service.</li><li>Exchange <code>direct</code> đảm bảo đúng 1 consumer instance xử lý 1 job — tránh double-publish.</li></ul><p><strong>Tiêu cực:</strong></p><ul><li>Thêm hạ tầng vận hành (RabbitMQ cluster, DLQ monitoring) so với REST đồng bộ đơn giản.</li><li>Eventual consistency — status Task/Post không cập nhật ngay lập tức, phải chờ callback (UX cần hiển thị trạng thái <code>PENDING</code>/<code>IN_PROGRESS</code> thay vì chờ đồng bộ).</li><li>Cần xử lý duplicate message (idempotency) nếu RabbitMQ redeliver do consumer crash giữa chừng — publisher-service dùng Redis dedup lock (xem <code>docs/architecture/</code> ghi chú <code>DA-E52-15</code>).</li></ul>',11)])])}const g=i(t,[["render",s]]);export{d as __pageData,g as default};
